package com.volcanicskiller;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class VolcanicSkillerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(VolcanicSkillerPlugin.class);
		RuneLite.main(args);
	}
}

package com.volcanicskiller;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;

@ConfigGroup(VolcanicSkillerConfig.GROUP)
public interface VolcanicSkillerConfig extends Config
{
	String GROUP = "volcanicskiller";

	/**
	 * Persisted key for the last-seen reward-point total. Written by the plugin
	 * via {@code ConfigManager} so the panel can show a value before the game
	 * transmits a fresh one after login. Not rendered as a config item.
	 */
	String REWARD_POINTS_KEY = "rewardPoints";

	@ConfigItem(
		keyName = "gameStartNotification",
		name = "Game start notification",
		description = "Notifies you when a Volcanic Mine game begins. Use the settings wheel to turn it on/off and configure delivery.",
		position = 1
	)
	default Notification gameStartNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "showRewardPointsOverlay",
		name = "Show reward points overlay",
		description = "Show the reward-point total as an overlay on the game screen.",
		position = 2
	)
	default boolean showRewardPointsOverlay()
	{
		return true;
	}
}

package com.volcanicskiller;

import java.awt.BorderLayout;
import java.awt.Font;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel that shows the tracked Volcanic Mine reward point total. Because
 * it lives in the RuneLite toolbar it is visible everywhere, including outside
 * the minigame instance. Values are read directly from the game, so the total
 * always reflects points earned and spent.
 */
class VolcanicSkillerPanel extends PluginPanel
{
	private static final String UNKNOWN = "—";

	private final JLabel rewardPointsValue = new JLabel(UNKNOWN, SwingConstants.CENTER);
	private final JLabel gamePointsValue = new JLabel(UNKNOWN, SwingConstants.CENTER);

	VolcanicSkillerPanel()
	{
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));

		content.add(statCard("Reward points", rewardPointsValue));
		content.add(Box.createVerticalStrut(8));
		content.add(statCard("Points this game", gamePointsValue));

		add(content, BorderLayout.NORTH);
	}

	private JPanel statCard(String title, JLabel valueLabel)
	{
		final JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		final JLabel titleLabel = new JLabel(title, SwingConstants.CENTER);
		titleLabel.setFont(titleLabel.getFont().deriveFont(Font.PLAIN, 11f));

		valueLabel.setFont(valueLabel.getFont().deriveFont(Font.BOLD, 20f));

		card.add(titleLabel, BorderLayout.NORTH);
		card.add(valueLabel, BorderLayout.CENTER);
		return card;
	}

	/** Must be called on the Swing EDT. */
	void setRewardPoints(int total)
	{
		rewardPointsValue.setText(format(total));
	}

	/** Must be called on the Swing EDT. */
	void setGamePoints(int points)
	{
		gamePointsValue.setText(format(points));
	}

	private static String format(int value)
	{
		return String.format("%,d", value);
	}
}

package com.volcanicskiller;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * On-screen overlay showing the tracked reward-point total (and the current
 * game's points while a game is running). Drawn on the game window so the total
 * is visible without opening the side panel.
 */
class VolcanicSkillerOverlay extends OverlayPanel
{
	private final VolcanicSkillerPlugin plugin;

	VolcanicSkillerOverlay(VolcanicSkillerPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		getPanelComponent().setPreferredSize(new Dimension(150, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isOverlayEnabled())
		{
			return null;
		}

		getPanelComponent().getChildren().clear();

		getPanelComponent().getChildren().add(TitleComponent.builder()
			.text("Volcanic Skiller")
			.color(Color.ORANGE)
			.build());

		getPanelComponent().getChildren().add(LineComponent.builder()
			.left("Reward points:")
			.right(String.format("%,d", plugin.getRewardPointsTotal()))
			.build());

		if (plugin.isInGame())
		{
			getPanelComponent().getChildren().add(LineComponent.builder()
				.left("This game:")
				.right(String.format("%,d", plugin.getCurrentGamePoints()))
				.build());
		}

		return super.render(graphics);
	}
}

package com.volcanicskiller;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Volcanic Skiller",
	description = "Tracks Volcanic Mine reward points outside the minigame and notifies you when a game starts",
	tags = {"volcanic", "mine", "skilling", "mining", "points", "notification", "minigame"}
)
public class VolcanicSkillerPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(VolcanicSkillerPlugin.class);

	// Minigame varbits (not exposed by the RuneLite API, so referenced directly).
	private static final int VARBIT_GAME_STATE = 5941;  // 0 = none, 1 = lobby, 2 = in game
	private static final int VARBIT_GAME_POINTS = 5934; // points earned in the current game (resets each game)

	private static final int GAME_STATE_IN_GAME = 2;

	// Petrified Pete's Ore Shop interface.
	private static final int SHOP_GROUP_ID = InterfaceID.FossilVolcanicShop.UNIVERSE >>> 16;

	@Inject
	private Client client;

	@Inject
	private VolcanicSkillerConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Notifier notifier;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	private VolcanicSkillerPanel panel;
	private NavigationButton navButton;
	private VolcanicSkillerOverlay overlay;

	private int gameState;
	private int currentGamePoints;
	// Highest per-game points seen this game. Points only rise during a game, so
	// the peak is the amount to bank on completion (ignores the reset to 0 on exit).
	private int gamePointsPeak;
	private int lastMiningXp = -1;
	private int rewardPointsTotal;
	private boolean shopOpen;

	@Provides
	VolcanicSkillerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(VolcanicSkillerConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new VolcanicSkillerPanel();

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Volcanic Skiller")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlay = new VolcanicSkillerOverlay(this);
		overlayManager.add(overlay);

		loadStoredTotal();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			initGameState();
		}
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);
		panel = null;
		navButton = null;
		overlay = null;
		gameState = 0;
		currentGamePoints = 0;
		gamePointsPeak = 0;
		lastMiningXp = -1;
		shopOpen = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			initGameState();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VARBIT_GAME_POINTS)
		{
			currentGamePoints = client.getVarbitValue(VARBIT_GAME_POINTS);
			gamePointsPeak = Math.max(gamePointsPeak, currentGamePoints);
			final int points = currentGamePoints;
			SwingUtilities.invokeLater(() -> panel.setGamePoints(points));
		}
		else if (event.getVarbitId() == VARBIT_GAME_STATE)
		{
			handleGameStateChange(client.getVarbitValue(VARBIT_GAME_STATE));
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// While the reward shop is open its "Points:" line shows the true balance
		// (including 0 after spending everything); keep the total synced to it.
		if (shopOpen)
		{
			syncFromShop();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.MINING)
		{
			return;
		}

		final int xp = event.getXp();
		// Volcanic Mine grants a lump of Mining experience when you leave a
		// completed game — the reliable signal that the game finished and points
		// were banked. Credit the points we tracked to the running total.
		if (lastMiningXp >= 0 && xp > lastMiningXp && gamePointsPeak > 0 && gameState != GAME_STATE_IN_GAME)
		{
			final int total = rewardPointsTotal + gamePointsPeak;
			setTotal(total);
			log.debug("Volcanic Mine completed: banked {} points on Mining XP gain, total now {}", gamePointsPeak, total);
			gamePointsPeak = 0;
		}
		lastMiningXp = xp;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == SHOP_GROUP_ID)
		{
			shopOpen = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == SHOP_GROUP_ID)
		{
			shopOpen = false;
		}
	}

	private void handleGameStateChange(int newState)
	{
		final int previousState = gameState;
		gameState = newState;

		if (newState == GAME_STATE_IN_GAME && previousState != GAME_STATE_IN_GAME)
		{
			gamePointsPeak = 0;
			notifier.notify(config.gameStartNotification(), "A Volcanic Mine game has started!");
			log.debug("Volcanic Mine game started");
		}
	}

	/**
	 * Corrects the total from the balance shown in Petrified Pete's reward shop.
	 * The shop's "Points:" line is the authoritative displayed value — accurate
	 * for every amount including 0 after spending everything — so it captures
	 * spending, which the earn-side tracking cannot see.
	 */
	private void syncFromShop()
	{
		final Integer points = readShopPointsFromScreen();
		if (points != null && points != rewardPointsTotal)
		{
			setTotal(points);
			log.debug("Shop sync: reward points = {}", points);
		}
	}

	/** Parses the shop's "Points: &lt;n&gt;" line, or returns null if not readable. */
	private Integer readShopPointsFromScreen()
	{
		final Widget widget = client.getWidget(InterfaceID.FossilVolcanicShop.POINTS);
		if (widget == null)
		{
			return null;
		}

		String text = widget.getText();
		if (text == null)
		{
			return null;
		}

		// Strip widget colour/format tags (e.g. <col=ffa82f>) before reading the
		// number, otherwise the hex colour would be parsed as part of it.
		text = text.replaceAll("<[^>]*>", "");
		final String digits = text.replaceAll("[^0-9]", "");
		if (digits.isEmpty())
		{
			return null;
		}

		try
		{
			return Integer.parseInt(digits);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * Seeds game/mining state from the current client values. Runs on every
	 * region load (each fires GameState.LOGGED_IN), so it must not disturb an
	 * in-progress game: it leaves the per-game peak alone and only sets the
	 * Mining-XP baseline once, so a completion XP gain is never missed.
	 */
	private void initGameState()
	{
		gameState = client.getVarbitValue(VARBIT_GAME_STATE);
		currentGamePoints = client.getVarbitValue(VARBIT_GAME_POINTS);

		if (lastMiningXp < 0)
		{
			lastMiningXp = client.getSkillExperience(Skill.MINING);
		}

		final int points = currentGamePoints;
		SwingUtilities.invokeLater(() -> panel.setGamePoints(points));
	}

	private void loadStoredTotal()
	{
		final Integer stored = configManager.getConfiguration(
			VolcanicSkillerConfig.GROUP, VolcanicSkillerConfig.REWARD_POINTS_KEY, Integer.class);
		rewardPointsTotal = stored == null ? 0 : stored;
		final int total = rewardPointsTotal;
		SwingUtilities.invokeLater(() -> panel.setRewardPoints(total));
	}

	/** Persists the total for offline display and reflects it in the UI. */
	private void setTotal(int total)
	{
		rewardPointsTotal = total;
		configManager.setConfiguration(
			VolcanicSkillerConfig.GROUP, VolcanicSkillerConfig.REWARD_POINTS_KEY, total);
		SwingUtilities.invokeLater(() -> panel.setRewardPoints(total));
	}

	// --- accessors for the overlay ---

	int getRewardPointsTotal()
	{
		return rewardPointsTotal;
	}

	int getCurrentGamePoints()
	{
		return currentGamePoints;
	}

	boolean isInGame()
	{
		return gameState == GAME_STATE_IN_GAME;
	}

	boolean isOverlayEnabled()
	{
		return config.showRewardPointsOverlay();
	}
}
